        [ex("Lola dice: «Solo era una broma, no pasa nada». ¿Qué le respondes?", "Que si una broma hiere o deja fuera a alguien, no es una broma", "Se debe pensar cómo se siente la otra persona."),
         ex("Teo dice: «Discriminar es tener amigos distintos a mí». ¿Qué error hay?", "Discriminar es tratar peor a alguien por cómo es", "Elegir amigos por gustos no es discriminar.")],
